package com.example.adblocker;

import android.app.job.JobParameters;
import android.app.job.JobService;
import android.content.Context;
import android.util.Log;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;

/** No VPN start, user notification or DNS history is generated by this job. */
public final class BlocklistRefreshJobService extends JobService {
    private static final String TAG = "AdBlockAutoRefresh";
    private volatile Run current;

    private static final class Run {
        final JobParameters params;
        final AtomicBoolean active = new AtomicBoolean(true);
        Thread thread;

        Run(JobParameters params) { this.params = params; }
    }

    @Override public boolean onStartJob(JobParameters params) {
        Context app = getApplicationContext();
        FilterSettings settings = new FilterSettings(app);
        if (!settings.autoRefreshEnabled() || AdBlockVpnService.isRunning
                || AdBlockVpnService.isStarting) {
            // An active VPN already checks and refreshes sources periodically.
            return false;
        }
        Run run = new Run(params);
        current = run;
        BooleanSupplier stillAllowed = () -> run.active.get()
                && settings.autoRefreshEnabled()
                && !AdBlockVpnService.isRunning && !AdBlockVpnService.isStarting;
        run.thread = new Thread(() -> {
            BlocklistRefreshStatus.Outcome result = BlocklistRefreshStatus.Outcome.FAILED;
            try {
                if (stillAllowed.getAsBoolean()) {
                    result = new BlocklistManager(app)
                            .refreshWithStatus(stillAllowed).outcome();
                }
            } catch (RuntimeException error) {
                Log.w(TAG, "Scheduled blocklist download failed", error);
            } finally {
                if (run.active.compareAndSet(true, false)) {
                    if (settings.autoRefreshEnabled()
                            && !AdBlockVpnService.isRunning
                            && !AdBlockVpnService.isStarting) {
                        settings.recordAutoRefresh(result);
                    }
                    if (current == run) current = null;
                    jobFinished(params, false);
                }
            }
        }, "ScheduledBlocklistRefresh");
        run.thread.start();
        return true;
    }

    @Override public boolean onStopJob(JobParameters params) {
        Run run = current;
        if (run != null && run.params == params) {
            run.active.set(false);
            if (run.thread != null) run.thread.interrupt();
            current = null;
        }
        return new FilterSettings(this).autoRefreshEnabled();
    }
}
